try:
    import numpy as np

    valid = df[df['row_kind'].isin(['sale', 'return', 'refunded', 'other_currency', 'non_product'])] \
        if 'row_kind' in df.columns else df.copy()

    valid = valid.copy()
    valid['run'] = valid['Planned Minutes'] - valid['Unplanned Downtime (min)'] - valid['Changeover (min)']
    valid['oee_num'] = valid['Ideal Cycle Time (s)'] * valid['Good Count'] / 60.0

    oee_by_line = valid.groupby('Line').agg(
        oee_num_sum=('oee_num', 'sum'),
        planned_sum=('Planned Minutes', 'sum')
    ).reset_index()
    oee_by_line['oee'] = oee_by_line['oee_num_sum'] / oee_by_line['planned_sum']

    oee_results = [
        {"name": str(row['Line']), "value": round(float(row['oee']), 6)}
        for _, row in oee_by_line.iterrows()
    ]

    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": oee_results
    })

    overall_oee = valid['oee_num'].sum() / valid['Planned Minutes'].sum()
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee_overall",
        "results": [{"name": "overall", "value": round(float(overall_oee), 6)}]
    })

    result['assumptions'].append(
        "OEE = sum(ideal_cycle_s × good_count / 60) / sum(planned_minutes); run = planned − unplanned − changeover (run used for availability context only)."
    )
    result['assumptions'].append(
        "Only rows with row_kind in [sale, return, refunded, other_currency, non_product] are included in OEE computation."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": [{"name": "error", "value": 0.0}]
    })
    result['assumptions'].append(f"OEE segmentation failed: {str(e)}")

