import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_prod = df[df['row_kind'].isin(['sale', 'non_product', 'other_currency']) == False] if 'row_kind' in df.columns else df.copy()
    df_prod = df[~df['row_kind'].isin(['test', 'cancel', 'cancelled', 'refunded'])] if 'row_kind' in df.columns else df.copy()
except Exception:
    df_prod = df.copy()

try:
    oee_by_line = []
    lines = df_prod['Line'].dropna().unique()
    for line in sorted(lines):
        grp = df_prod[df_prod['Line'] == line]
        sum_planned = grp['Planned Minutes'].sum()
        sum_ideal_good = (grp['Ideal Cycle Time (s)'] * grp['Good Count'] / 60.0).sum()
        oee_val = sum_ideal_good / sum_planned if sum_planned > 0 else float('nan')
        oee_by_line.append({"name": str(line), "value": round(float(oee_val), 6)})

    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": oee_by_line
    })
except Exception as e:
    result['assumptions'].append(f"OEE by line segment failed: {e}")

try:
    overall_planned = df_prod['Planned Minutes'].sum()
    overall_ideal_good = (df_prod['Ideal Cycle Time (s)'] * df_prod['Good Count'] / 60.0).sum()
    overall_oee = overall_ideal_good / overall_planned if overall_planned > 0 else float('nan')
    result['assumptions'].append(f"OEE = sum(ideal_cycle_s * good_count / 60) / sum(planned_minutes); overall OEE = {overall_oee:.4f}")
    result['assumptions'].append("row_kind filter excludes test and cancelled rows before OEE computation.")
    result['assumptions'].append("Ideal Cycle Time (s) used per-row as given; OEE pooled across shifts per line (not mean of shift OEEs).")
except Exception as e:
    result['assumptions'].append(f"Overall OEE note failed: {e}")

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

