import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    valid = df[df['row_kind'].isin(['sale', 'return', 'refunded', 'other_currency', 'non_product', 'other'])] \
        if 'row_kind' in df.columns else df.copy()

    oee_by_line = (
        valid.groupby('Line')
        .apply(lambda g: (
            (g['Ideal Cycle Time (s)'] * g['Good Count']).sum() / 60.0
        ) / g['Planned Minutes'].sum()
        )
        .reset_index()
        .rename(columns={0: 'oee'})
    )

    oee_by_line = oee_by_line.sort_values('oee', ascending=False)

    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": [
            {"name": str(row['Line']), "value": round(float(row['oee']), 6)}
            for _, row in oee_by_line.iterrows()
        ]
    })

    result['assumptions'].append(
        "OEE = sum(ideal_cycle_s × good_count / 60) / sum(planned_minutes) per line; "
        "only non-test row_kind rows included."
    )
    result['assumptions'].append(
        "run time not used in OEE numerator per domain formula; denominator is planned_minutes."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Line",
        "metric_column": "Good Count",
        "aggregation": "ratio",
        "label": "oee",
        "results": [{"name": "error", "value": 0.0}]
    })
    result['assumptions'].append(f"OEE segmentation failed: {str(e)}")

