        asset_mttr.append({"name": str(asset), "value": round(a_mttr, 4), "_total": a_hours})

    asset_mttr_sorted = sorted(asset_mttr, key=lambda x: x['_total'], reverse=True)[:10]
    for r in asset_mttr_sorted:
        del r['_total']

    result['segments'].append({
        "segment_column": "ASSETNUM",
        "metric_column": "ACTFINISH",
        "aggregation": "ratio",
        "label": "mttr_hours",
        "results": asset_mttr_sorted
