    shift_groups_f = [g for g in shift_groups if len(g) >= 2]

    if len(shift_groups_f) >= 2:
        f_stat, p_val = sp_stats.f_oneway(*shift_groups_f)
        f_stat = float(f_stat)
        p_val = float(p_val)
        interp = f"One-way ANOVA on run minutes across shifts: F={f_stat:.3f}, p={p_val:.3g}. "
        if p_val < 0.05:
