        f2, p2 = sp_stats.f_oneway(*shift_avail_groups_f)
        f2 = float(f2)
        p2 = float(p2)
        interp2 = f"One-way ANOVA on row-level availability across shifts: F={f2:.3f}, p={p2:.3g}. "
