        else:
            interp2 += "No significant difference in availability across shifts."
        result['statistical_tests'].append({
            "test_name": "One-way ANOVA: availability by Shift",
            "statistic": round(f2, 4),
            "p_value": round(p2, 6),
            "interpretation": interp2
        })

