}

try:
    import numpy as np

    # Filter to product rows only (exclude test, cancel, etc.)
    df_prod = df[df['row_kind'].isin(['sale', 'return', 'refunded', 'other_currency', 'non_product', 'other'])]
    # Actually, for shift reports keep all non-test, non-cancel rows
    df_work = df[~df['row_kind'].isin(['test', 'cancel'])]

    # Compute availability per shift group:
    # run = planned_minutes - unplanned_downtime - changeover
    # availability = sum(run) / sum(planned_minutes)

    shift_groups = df_work.groupby('Shift')

    avail_results = []
    for shift_name, grp in shift_groups:
        planned = grp['Planned Minutes'].sum()
        unplanned = grp['Unplanned Downtime (min)'].sum()
        changeover = grp['Changeover (min)'].sum()
        run = planned - unplanned - changeover
        availability = run / planned if planned > 0 else np.nan
        avail_results.append({"name": str(shift_name), "value": float(round(availability, 6)) if not np.isnan(availability) else 0.0})

    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "ratio",
        "label": "availability",
        "results": avail_results
    })

    # Also break down Unplanned Downtime (min) sum by Shift
    ud_by_shift = df_work.groupby('Shift')['Unplanned Downtime (min)'].sum().reset_index()
    ud_results = [{"name": str(row['Shift']), "value": float(row['Unplanned Downtime (min)'])} for _, row in ud_by_shift.iterrows()]
    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Unplanned Downtime (min)",
        "aggregation": "sum",
        "label": None,
        "results": ud_results
