    pm_results = [{"name": str(row['Shift']), "value": float(row['Planned Minutes'])} for _, row in pm_by_shift.iterrows()]
    result['segments'].append({
        "segment_column": "Shift",
        "metric_column": "Planned Minutes",
        "aggregation": "sum",
        "label": None,
        "results": pm_results
    })

    # Availability by Shift x Line (two-column breakdown)
    shift_line_groups = df_work.groupby(['Shift', 'Line'])
    sl_results = []
    for (shift_name, line_name), grp in shift_line_groups:
        planned = grp['Planned Minutes'].sum()
