        availability = run / planned if planned > 0 else np.nan
        sl_results.append({"name": f"{shift_name}|{line_name}", "value": float(round(availability, 6)) if not np.isnan(availability) else 0.0})

    result['segments'].append({
        "segment_column": "Shift|Line",
        "metric_column": "Planned Minutes",
        "aggregation": "ratio",
        "label": "availability",
        "results": sl_results
