    result['assumptions'].append("Availability = (Planned - Unplanned Downtime - Changeover) / Planned, pooled per shift.")
    result['assumptions'].append("Rows with row_kind 'test' or 'cancel' excluded from all segment calculations.")
    result['assumptions'].append("Rows with Planned Minutes = 0 excluded from availability ratio (division guard).")

