import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df_prod = df[df['row_kind'].isin(['sale', 'non_product', 'other_currency']) == False].copy()
    df_prod = df[~df['row_kind'].isin(['test', 'cancel', 'cancelled'])].copy()
except Exception:
    df_prod = df.copy()

try:
    df_prod['run'] = df_prod['Planned Minutes'] - df_prod['Unplanned Downtime (min)'] - df_prod['Changeover (min)']
    df_prod['run'] = df_prod['run'].clip(lower=0)

    mtbf_by_machine = df_prod.groupby('Machine').apply(
        lambda g: (g['run'].sum() / 60) / g['Failures'].sum() if g['Failures'].sum() > 0 else float('nan')
    ).reset_index()
    mtbf_by_machine.columns = ['Machine', 'MTBF_hours']

    mtbf_results = []
    for _, row in mtbf_by_machine.iterrows():
        mtbf_results.append({
            "name": str(row['Machine']),
            "value": round(float(row['MTBF_hours']), 4) if not (row['MTBF_hours'] != row['MTBF_hours']) else float('nan')
        })

    mtbf_results_clean = [r for r in mtbf_results if r['value'] == r['value']]
    mtbf_results_clean.sort(key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Machine",
        "metric_column": "Failures",
        "aggregation": "ratio",
        "label": "mtbf_hours",
        "results": mtbf_results_clean
